CREATE TABLE IF NOT EXISTS deletion_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),target_type text NOT NULL CHECK(target_type IN ('application','photo')),target_id text NOT NULL,office_name text,reason text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','completed','cancelled')),requested_by uuid REFERENCES users(id),decided_by uuid REFERENCES users(id),decision_note text,decided_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_deletion_requests_status_created ON deletion_requests(status,created_at DESC);
CREATE TABLE IF NOT EXISTS role_change_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),current_role text NOT NULL,requested_role text NOT NULL,effective_date date,reason text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','applied','cancelled')),requested_by uuid REFERENCES users(id),decided_by uuid REFERENCES users(id),decision_note text,decided_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_role_change_requests_status_created ON role_change_requests(status,created_at DESC);
CREATE TABLE IF NOT EXISTS access_review_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),review_date date NOT NULL,target_count integer NOT NULL DEFAULT 0,issue_count integer NOT NULL DEFAULT 0,next_review_date date,notes text,reviewed_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
